#include <limits.h>
#include <stddef.h>
#include <stdio.h>

struct Expense {
    const char *category;
    long long cents;
};

static int add_expense(const struct Expense *expense, long long *total)
{
    if (expense == NULL || total == NULL || expense->category == NULL ||
        expense->cents < 0 || *total < 0 ||
        expense->cents > LLONG_MAX - *total) {
        return 0;
    }
    *total += expense->cents;
    return 1;
}

static int monthly_total(const struct Expense expenses[], size_t count,
                         long long *total_out)
{
    size_t i;
    long long total = 0;

    if (total_out == NULL || (count > 0U && expenses == NULL)) {
        return 0;
    }
    for (i = 0U; i < count; ++i) {
        if (!add_expense(&expenses[i], &total)) {
            return 0;
        }
    }
    *total_out = total;
    return 1;
}

int main(void)
{
    const struct Expense expenses[] = {
        {"Travel", 1250}, {"Food", 2899}, {"Books", 1599}
    };
    long long total;

    if (!monthly_total(expenses, sizeof expenses / sizeof expenses[0], &total)) {
        fputs("invalid expense data\n", stderr);
        return 1;
    }
    printf("Monthly expenses: %lld cents\n", total);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

struct Product {
    unsigned int id;
    int quantity;
};

static int change_stock(struct Product products[], size_t count,
                        unsigned int id, int change)
{
    size_t i;

    if (count > 0U && products == NULL) {
        return 0;
    }
    for (i = 0U; i < count; ++i) {
        if (products[i].id == id) {
            long long updated;
            if (products[i].quantity < 0 || products[i].quantity > 1000000) {
                return 0;
            }
            updated = (long long)products[i].quantity + (long long)change;
            if (updated < 0LL || updated > 1000000LL) {
                return 0;
            }
            products[i].quantity = (int)updated;
            return 1;
        }
    }
    return 0;
}

static void print_stock(const struct Product products[], size_t count)
{
    size_t i;
    for (i = 0U; i < count; ++i) {
        printf("id=%u quantity=%d\n", products[i].id, products[i].quantity);
    }
}

int main(void)
{
    struct Product products[] = {{101U, 8}, {205U, 3}, {310U, 0}};
    const size_t count = sizeof products / sizeof products[0];

    if (!change_stock(products, count, 205U, 4) ||
        !change_stock(products, count, 101U, -2)) {
        fputs("stock update rejected\n", stderr);
        return 1;
    }
    print_stock(products, count);
    return 0;
}

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int write_report(FILE *stream, const char *name, int score)
{
    if (stream == NULL || name == NULL || name[0] == '\\0' ||\n        strchr(name, '|') != NULL || strchr(name, '\\n') != NULL ||\n        score < 0 || score > 100) {
        return 0;
    }
    if (fprintf(stream, "%s|%d\n", name, score) < 0) {
        return 0;
    }
    return fflush(stream) == 0;
}

static int read_report(FILE *stream, char name[], size_t capacity, int *score_out)
{
    char line[128];
    char *separator;
    char *end;
    long parsed;

    if (stream == NULL || name == NULL || capacity == 0U || score_out == NULL) {
        return 0;
    }
    if (fgets(line, sizeof line, stream) == NULL) {
        return 0;
    }
    if (strchr(line, '\\n') == NULL) {
        return 0;
    }
    separator = strchr(line, '|');
    if (separator == NULL) {
        return 0;
    }
    *separator = '\\0';
    if (line[0] == '\\0' || strlen(line) >= capacity) {
        return 0;
    }
    errno = 0;
    parsed = strtol(separator + 1, &end, 10);
    if (separator[1] == '\\0' || end == separator + 1 ||
        (*end != '\\n' && *end != '\\0') || errno == ERANGE ||
        parsed < 0 || parsed > 100) {
        return 0;
    }
    (void)strcpy(name, line);
    *score_out = (int)parsed;
    return 1;
}

int main(void)
{
    FILE *stream = tmpfile();
    char name[32];
    int score;

    if (stream == NULL) {
        fputs("temporary stream unavailable\\n", stderr);
        return 1;
    }
    if (!write_report(stream, "Mira", 86) ||
        fseek(stream, 0L, SEEK_SET) != 0 ||
        !read_report(stream, name, sizeof name, &score)) {
        (void)fclose(stream);
        fputs("report operation failed\\n", stderr);
        return 1;
    }
    printf("Learner: %s, score: %d\\n", name, score);
    if (fclose(stream) != 0) {
        fputs("close failed\\n", stderr);
        return 1;
    }
    return 0;
}
